 DirectorCatalog director;director.dynamic_subjects=true;director.military_appointments=true;director.policies.insert("policy",policy);DirectorState state;FinitePlan plan;plan.subject=known.subject;plan.policy_id="policy";plan.template_id="military_appointment";plan.goal_ref=order;plan.phase=PlanPhase::completed;state.plans.insert("new",plan);need(validate_political_military_director(director,state,&f.catalog,&f.state),"completed original acceptance cold validates");state.plans.find("new")->subject.id="outsider";check(!validate_political_military_director(director,state,&f.catalog,&f.state).ok,"forged NPC listener plan rejected");
 need(invalidate_office(f.common,f.offices,f.organizations,"lord.office",0,answered),"actual issuer revoked");check(!need(propose_director_military_appointment(c,travel,known,policy,base),"lost authority ignored"),"accepted stale authority cannot be applied");std::cout<<"political military NPC checks="<<checks<<" failures=0\n";return 0;
